list_tax_zones.code:
use WebCommander\Sdk\Resources\TaxZones\TaxZones;

$response = TaxZones::listTaxZones($client, ['limit' => 2]);

foreach ($response->map['tax_zones'] as $zone) {
    echo $zone['id'], ' ', $zone['name'], PHP_EOL;
}
echo $response->map['pagination']['total'], ' tax zones in total', PHP_EOL;

get_tax_zone.code:
use WebCommander\Sdk\Resources\TaxZones\TaxZones;

$response = TaxZones::getTaxZone($client, 1);

$zone = $response->map['tax_zone'];
echo $zone['name'], PHP_EOL;
foreach ($zone['states'] as $state) {
    echo 'state ', $state['id'], ' ', $state['name'], PHP_EOL;
}

